"btn ghost small block\" id=\"btn-logout\" type=\"button\">Log out</button>\n      </div>\n    </aside>\n\n    <main class=\"main\">\n      <div class=\"toolbar\">\n        <h1>My Videos</h1>\n        <span class=\"toolbar-note\" id=\"library-note\">—</span>\n        <div class=\"spacer\"></div>\n        <button class=\"btn\" id=\"btn-upload\" type=\"button\">+ Upload Video</button>\n      </div>\n\n      <!-- Upload panel -->\n      <div id=\"upload-panel\" class=\"card hidden mb-20\">\n        <div id=\"dropzone\" class=\"dropzone\">\n          <div class=\"dz-title\">Drag &amp; Drop video here</div>\n          <div class=\"dz-sub\">or click to Browse · MP4, MOV, AVI, MKV, WEBM</div>\n          <input id=\"file-input\" type=\"file\" class=\"hidden\" accept=\"video/*,.mp4,.mov,.avi,.mkv,.webm\" />\n        </div>\n        <div id=\"upload-progress-wrap\" class=\"hidden mt-12\">\n          <div class=\"progress\"><span id=\"upload-progress-bar\"></span></div>\n          <div class=\"progress-bar-label\" id=\"upload-progress-label\"></div>\n        </div>\n        <div class=\"auth-err\" id=\"upload-err\"></div>\n      </div>\n\n      <div id=\"videos-empty\" class=\"empty-state\">\n        <div class=\"empty-icon\">🎞️</div>\n        <div>No videos yet. Upload a video and it will appear here, waiting for processing.</div>\n        <div class=\"empty-cta\"><button class=\"btn\" id=\"empty-upload\" type=\"button\">+ Upload your first video</button></div>\n      </div>\n      <div id=\"videos-table\" class=\"table-wrap table-scroll hidden\">\n        <table>\n          <thead>\n            <tr>\n              <th>Filename</th>\n              <th>Size</th>\n              <th>Duration</th>\n              <th>Uploaded</th>\n              <th>Frames</th>\n              <th>Chunks</th>\n              <th>Status</th>\n            </tr>\n          </thead>\n          <tbody id=\"videos-body\"></tbody>\n        </table>\n      </div>\n    </main>\n  </div>\n\n  <div class=\"toast-wrap\" id=\"toast-wrap\"></div>\n  <script src=\"/js/api.js\"></script>\n  <script src=\"/js/user.js\"></script>\n</body>\n</html>\n";

export const adminHtml: string = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>KENDUIT — Admin Portal</title>\n  <link rel=\"stylesheet\" href=\"/css/frameforge.css\" />\n</head>\n<body>\n  <!-- Auth view -->\n  <div id=\"view-auth\" class=\"auth-wrap\">\n    <div class=\"card auth-card\">\n      <div class=\"brand\" style=\"padding:0 0 16px;\">\n        <span class=\"logo\">KEN<span class=\"accent\">DUIT</span></span>\n        <span class=\"ver\">ADMIN</span>\n      </div>\n      <div class=\"auth-tabs\"><button class=\"active\" type=\"button\">Admin Login</button></div>\n      <form id=\"auth-form\">\n        <div class=\"field\">\n          <label for=\"auth-email\">Email</label>\n          <input id=\"auth-email\" class=\"input\" type=\"email\" autocomplete=\"email\" required placeholder=\"admin@example.com\" />\n        </div>\n        <div class=\"field\">\n          <label for=\"auth-password\">Password</label>\n          <input id=\"auth-password\" class=\"input\" type=\"password\" autocomplete=\"current-password\" required placeholder=\"••••••••\" />\n        </div>\n        <button class=\"btn block\" id=\"auth-submit\" type=\"submit\">Login</button>\n        <div class=\"auth-err\" id=\"auth-err\"></div>\n      </form>\n    </div>\n  </div>\n\n  <!-- App view -->\n  <div id=\"view-app\" class=\"app-shell hidden\">\n    <aside class=\"sidebar\">\n      <div class=\"brand\">\n        <span class=\"logo\">KEN<span class=\"accent\">DUIT</span></span>\n        <span class=\"ver\">ADMIN</span>\n      </div>\n      <div class=\"nav\">\n        <a href=\"#\" data-filter=\"all\" class=\"active\">Dashboard</a>\n        <a href=\"#\" data-filter=\"uploaded\">Uploads</a>\n        <a href=\"#\" data-filter=\"queued\">Processing</a>\n        <a href=\"#\" data-filter=\"completed\">Completed</a>\n        <a href=\"#\" data-filter=\"failed\">Failed</a>\n      </div>\n      <div class=\"sidebar-footer\">\n        <div class=\"user-email\" id=\"user-email\"></div>\n        <button class=\"btn ghost small block\" id=\"btn-logout\" type=\"button\">Log out</button>\n      </div>\n    </aside>\n\n    <main class=\"main\">\n      <!-- Videos table view -->\n      <div id=\"view-videos\">\n        <div class=\"toolbar\">\n          <h1 id=\"view-title\">Dashboard</h1>\n          <div class=\"spacer\"></div>\n          <input id=\"search-input\" class=\"input\" style=\"max-width:240px;\" placeholder=\"Search user or filename…\" />\n        </div>\n\n        <div class=\"grid cols-4 mb-20\" id=\"stats-row\">\n          <div class=\"stat-card\">\n            <div class=\"stat-label\"><span class=\"dot dot-brand\"></span>Uploaded</div>\n            <div class=\"stat-value\" id=\"stat-uploaded\">0</div>\n            <div class=\"stat-sub\">waiting for processing</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-label\"><span class=\"dot dot-warn\"></span>Processing</div>\n            <div class=\"stat-value\" id=\"stat-queued\">0</div>\n            <div class=\"stat-sub\">queued or in progress</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-label\"><span class=\"dot dot-ok\"></span>Completed</div>\n            <div class=\"stat-value\" id=\"stat-completed\">0</div>\n            <div class=\"stat-sub\">frames extracted</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-label\"><span class=\"dot dot-soft\"></span>Total</div>\n            <div class=\"stat-value\" id=\"stat-total\">0</div>\n            <div class=\"stat-sub\">all videos on the platform</div>\n          </div>\n        </div>\n\n        <div id=\"jobs-empty\" class=\"empty-state hidden\">\n          <div class=\"empty-icon\">🎬</div>\n          <div>No jobs in this view.</div>\n          <div class=\"empty-cta\"><button class=\"btn ghost small\" id=\"empty-clear-filter\" type=\"button\">Show all jobs</button></div>\n        </div>\n        <div id=\"jobs-table\" class=\"table-wrap table-scroll hidden\">\n          <table>\n            <thead>\n              <tr>\n                <th>User</th><th>Filename</th><th>Size</th><th>Duration</th>\n                <th>Resolution</th><th>Uploaded</th><th>Status</th><th>Frames</th><th>Chunks</th><th>Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"jobs-body\"></tbody>\n          </table>\n        </div>\n        <div class=\"pager\">\n          <button class=\"btn ghost small\" id=\"prev-page\" type=\"button\">‹ Prev</button>\n          <span class=\"pager-info\" id=\"page-info\">Page 1</span>\n          <button class=\"btn ghost small\" id=\"next-page\" type=\"button\">Next ›</button>\n        </div>\n      </div>\n\n      <!-- Job detail view -->\n      <div id=\"view-job\" class=\"hidden\">\n        <div class=\"toolbar\">\n          <button class=\"btn ghost small\" id=\"back-btn\" type=\"button\">← Back</button>\n          <h1 id=\"job-title\">Job</h1>\n          <span class=\"badge\" id=\"job-status-badge\"></span>\n        </div>\n\n        <!-- Job info -->\n        <div class=\"card mb-20\">\n          <div class=\"meta-grid\" id=\"job-meta\"></div>\n          <div class=\"divider\"></div>\n          <div class=\"row gap-8\" id=\"job-actions\"></div>\n          <div class=\"auth-err\" id=\"job-err\"></div>\n        </div>\n\n        <!-- Process config -->\n        <div class=\"card mb-20\" id=\"process-panel\">\n          <h3>Extraction Settings</h3>\n          <div class=\"row gap-8 mt-12\">\n            <label class=\"muted small\">Mode:</label>\n            <select id=\"mode-select\" class=\"input\" style=\"max-width:200px;\">\n              <option value=\"Every Frame\">Every Frame</option>\n              <option value=\"10 fps\">10 fps</option>\n              <option value=\"5 fps\">5 fps</option>\n              <option value=\"3 fps\">3 fps</option>\n              <option value=\"2 fps\">2 fps</option>\n              <option value=\"1 fps\" selected>1 fps</option>\n              <option value=\"Smart Scene\">Smart Scene</option>\n              <option value=\"1 per 5 s\">1 per 5 s</option>\n              <option value=\"Thumb Strip\">Thumb Strip</option>\n              <option value=\"Custom FPS\">Custom FPS</option>\n            </select>\n            <div id=\"custom-fps-wrap\" class=\"hidden\">\n              <label class=\"muted small\">FPS:</label>\n              <input id=\"custom-fps\" class=\"input\" type=\"number\" min=\"0.1\" max=\"120\" step=\"0.5\" value=\"1\" style=\"width:90px;\" />\n            </div>\n          </div>\n          <div class=\"row gap-8 mt-12\">\n            <label class=\"muted small\">Sharpness: <span id=\"sharp-val\">1.0</span></label>\n            <input id=\"sharpness\" type=\"range\" min=\"0.5\" max=\"3.0\" step=\"0.1\" value=\"1.0\" style=\"width:220px;\" />\n            <label class=\"muted small\">Scene threshold: <span id=\"scene-val\">30</span></label>\n            <input id=\"scene-threshold\" type=\"range\" min=\"5\" max=\"80\" step=\"1\" value=\"30\" style=\"width:220px;\" />\n          </div>\n          <button class=\"btn mt-12\" id=\"start-process\" type=\"button\">Start Processing</button>\n        </div>\n\n        <!-- Progress -->\n        <div class=\"card mb-20 hidden\" id=\"progress-panel\">\n          <div class=\"card-header\">\n            <h3>Progress</h3>\n            <span class=\"badge\" id=\"progress-status-badge\"></span>\n          </div>\n          <div class=\"progress\"><span id=\"progress-bar\"></span></div>\n          <div class=\"progress-bar-label\" id=\"progress-label\"></div>\n          <div class=\"mt-12 progress\" style=\"display:none;\" id=\"chunk-progress-wrap\">\n            <span id=\"chunk-progress-bar\"></span>\n          </div>\n          <div class=\"progress-bar-label\" id=\"chunk-progress-label\" style=\"display:none;\"></div>\n        </div>\n\n        <!-- Frame gallery -->\n        <div class=\"card\" id=\"gallery-panel\">\n          <div class=\"toolbar\">\n            <h3>Frame Gallery</h3>\n            <span class=\"toolbar-note\">extracted frames</span>\n            <div class=\"spacer\"></div>\n            <span class=\"pager-info\" id=\"sel-count\">0 selected</span>\n            <button class=\"btn ghost small\" id=\"select-all\" type=\"button\">Select all</button>\n            <button class=\"btn ghost small\" id=\"deselect-all\" type=\"button\">Deselect</button>\n            <button class=\"btn danger small\" id=\"delete-selected\" type=\"button\">Delete selected</button>\n            <button class=\"btn small\" id=\"export-all\" type=\"button\">ZIP all</button>\n            <button class=\"btn small\" id=\"export-selected\" type=\"button\">ZIP selected</button>\n          </div>\n          <div id=\"gallery-empty\" class=\"empty-state hidden\">\n            <div class=\"empty-icon\">🖼️</div>\n            <div>No frames extracted yet.</div>\n            <div class=\"empty-cta\"><button class=\"btn small\" id=\"empty-start-process\" type=\"button\">Start processing</button></div>\n          </div>\n          <div class=\"gallery\" id=\"gallery\"></div>\n          <div class=\"pager\" id=\"gallery-pager\">\n            <button class=\"btn ghost small\" id=\"gal-prev\" type=\"button\">‹ Prev</button>\n            <span class=\"pager-info\" id=\"gal-info\">0 frames</span>\n            <button class=\"btn ghost small\" id=\"gal-next\" type=\"button\">Next ›</button>\n          </div>\n        </div>\n\n        <!-- Chunks (scene-based split) -->\n        <div class=\"card\" id=\"chunks-panel\">\n          <div class=\"toolbar\">\n            <h3>Scene Chunks</h3>\n            <span class=\"badge\" id=\"chunk-status-badge\" style=\"margin-left:8px;\"></span>\n            <div class=\"spacer\"></div>\n            <span class=\"pager-info\" id=\"chunk-sel-count\">0 selected</span>\n            <button class=\"btn ghost small\" id=\"chunk-select-all\" type=\"button\">Select all</button>\n            <button class=\"btn ghost small\" id=\"chunk-deselect-all\" type=\"button\">Deselect</button>\n            <button class=\"btn danger small\" id=\"chunk-delete-selected\" type=\"button\">Delete selected</button>\n            <button class=\"btn small\" id=\"chunk-export-all\" type=\"button\">ZIP all</button>\n            <button class=\"btn small\" id=\"chunk-export-selected\" type=\"button\">ZIP selected</button>\n          </div>\n          <div id=\"chunks-empty\" class=\"empty-state hidden\">\n            <div class=\"empty-icon\">✂️</div>\n            <div>No chunks yet. Split this video by background change.</div>\n            <div class=\"empty-cta\"><button class=\"btn small\" id=\"empty-split\" type=\"button\">Split into Chunks</button></div>\n          </div>\n          <div class=\"gallery\" id=\"chunks-gallery\"></div>\n          <div class=\"pager\" id=\"chunks-pager\">\n            <button class=\"btn ghost small\" id=\"chunk-prev\" type=\"button\">‹ Prev</button>\n            <span class=\"pager-info\" id=\"chunk-info\">0 chunks</span>\n            <button class=\"btn ghost small\" id=\"chunk-next\" type=\"button\">Next ›</button>\n          </div>\n        </div>\n      </div>\n    </main>\n  </div>\n\n  <!-- Export status modal -->\n  <div class=\"modal-backdrop hidden\" id=\"export-modal\">\n    <div class=\"modal\">\n      <div class=\"modal-header\"><h3>Export</h3><button class=\"btn ghost small\" id=\"export-close\" type=\"button\">Close</button></div>\n      <div class=\"modal-body\">\n        <div class=\"row gap-8\" id=\"export-status-row\">\n          <div class=\"spinner\"></div>\n          <span id=\"export-status-text\">Creating ZIP…</span>\n        </div>\n        <div class=\"auth-err\" id=\"export-err\"></div>\n      </div>\n      <div class=\"modal-footer\" id=\"export-footer\" style=\"display:none;\">\n        <a id=\"export-download\" class=\"btn\" download>Download ZIP</a>\n      </div>\n    </div>\n  </div>\n\n  <!-- Frame preview modal -->\n  <div class=\"modal-backdrop hidden\" id=\"preview-modal\">\n    <div class=\"modal\">\n      <div class=\"modal-header\">\n        <h3 id=\"preview-title\">Frame Preview</h3>\n        <button class=\"btn ghost small\" id=\"preview-close\" type=\"button\">Close</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"preview-img-wrap\"><img id=\"preview-img\" alt=\"frame\" /></div>\n        <div class=\"pager\" id=\"preview-pager\">\n          <button class=\"btn ghost small\" id=\"preview-prev\" type=\"button\">‹ Prev</button>\n          <span class=\"pager-info\" id=\"preview-info\"></span>\n          <button class=\"btn ghost small\" id=\"preview-next\" type=\"button\">Next ›</button>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <a id=\"preview-download\" class=\"btn\" download>Download JPEG</a>\n        <button class=\"btn ghost\" id=\"preview-toggle-select\" type=\"button\">Select</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"toast-wrap\" id=\"toast-wrap\"></div>\n  <script src=\"/js/api.js\"></script>\n  <script src=\"/js/admin.js\"></script>\n</body>\n</html>\n";

export const frameforgeCss: string = "/* ─────────────────────────────────────────────────────────────\n   KENDUIT — dark theme\n   Brand palette: #aa0000 (primary red) + #880000 (deep red).\n   ───────────────────────────────────────────────────────────── */\n:root {\n  --bg: #0a0a0c;\n  --surface: #131316;\n  --card: #18181c;\n  --border: #2b2b33;\n  --brand: #aa0000;\n  --brand-dark: #880000;\n  --red-soft: #ff7b7b;          /* readable red accent text on dark */\n  --red-faint: rgba(170, 0, 0, 0.14);\n  --red-glow: rgba(170, 0, 0, 0.35);\n  --text: #f4f4f7;\n  --muted: #7d7d8a;\n  --danger: #ff4757;\n  --btn-fg: #ffffff;\n  --mono: \"Courier New\", ui-monospace, SFMono-Regular, monospace;\n  --ui: \"Segoe UI\", system-ui, -apple-system, sans-serif;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nhtml, body { height: 100%; }\n\nbody {\n  background: radial-gradient(1100px 520px at 82% -8%, var(--red-faint), transparent 60%), var(--bg);\n  background-attachment: fixed;\n  color: var(--text);\n  font-family: var(--ui);\n  font-size: 14px;\n  line-height: 1.5;\n  min-height: 100vh;\n}\n\na { color: var(--red-soft); text-decoration: none; }\na:hover { text-decoration: underline; }\n\n/* ── Typography ───────────────────────────────────────────── */\n.mono { font-family: var(--mono); }\n.muted { color: var(--muted); }\n.small { font-size: 12px; }\n.hidden { display: none !important; }\n\nh1, h2, h3 { font-weight: 700; }\nh1 { font-size: 22px; letter-spacing: 0.5px; }\nh2 { font-size: 17px; }\nh3 { font-size: 14px; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); }\n\n/* ── Layout ───────────────────────────────────────────────── */\n.app-shell { display: flex; min-height: 100vh; }\n\n.sidebar {\n  position: relative;\n  width: 250px;\n  min-width: 250px;\n  background: var(--surface);\n  border-right: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  position: sticky;\n  top: 0;\n  height: 100vh;\n}\n/* Red accent strip along the top of the sidebar */\n.sidebar::before {\n  content: \"\";\n  position: absolute;\n  top: 0; left: 0; right: 0;\n  height: 3px;\n  background: linear-gradient(90deg, var(--brand) 0%, var(--brand-dark) 100%);\n}\n\n.main { flex: 1; padding: 28px 36px; overflow-x: hidden; }\n\n.brand {\n  padding: 20px 20px 16px;\n  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n}\n.brand .logo {\n  font-family: var(--mono);\n  font-weight: 700;\n  font-size: 22px;\n  letter-spacing: 1px;\n  text-shadow: 0 0 18px var(--red-glow);\n}\n.brand .logo .accent {\n  background: linear-gradient(120deg, var(--red-soft) 0%, var(--brand) 55%, var(--brand-dark) 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n.brand .ver { color: var(--muted); font-family: var(--mono); font-size: 11px; }\n\n.nav { padding: 14px 0; flex: 1; }\n.nav a {\n  display: block;\n  padding: 10px 20px;\n  color: var(--muted);\n  font-family: var(--mono);\n  font-size: 12px;\n  letter-spacing: 0.5px;\n  text-decoration: none;\n  border-left: 3px solid transparent;\n  transition: background 0.12s, color 0.12s;\n}\n.nav a:hover { background: var(--card); color: var(--text); }\n.nav a.active {\n  color: var(--red-soft);\n  border-left-color: var(--brand);\n  background: linear-gradient(90deg, var(--red-faint), transparent);\n  box-shadow: inset 0 0 12px rgba(170, 0, 0, 0.08);\n}\n\n.sidebar-footer { padding: 16px 20px; border-top: 1px solid var(--border); }\n.sidebar-footer .user-email {\n  color: var(--muted); font-size: 12px; word-break: break-all; margin-bottom: 8px;\n}\n\n/* ── Buttons ──────────────────────────────────────────────── */\n.btn {\n  font-family: var(--mono);\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: 0.3px;\n  border: none;\n  border-radius: 5px;\n  padding: 9px 14px;\n  cursor: pointer;\n  color: var(--btn-fg);\n  background: linear-gradient(135deg, var(--brand) 0%, var(--brand-dark) 100%);\n  box-shadow: 0 3px 12px var(--red-glow);\n  transition: filter 0.15s, transform 0.1s, box-shadow 0.15s;\n}\n.btn:hover { filter: brightness(1.18); box-shadow: 0 4px 16px var(--red-glow); }\n.btn:active { transform: translateY(1px); }\n.btn:disabled { opacity: 0.4; cursor: not-allowed; box-shadow: none; filter: none; }\n.btn.ghost { background: var(--border); color: var(--text); box-shadow: none; }\n.btn.ghost:hover { background: #3a3a46; filter: none; }\n.btn.danger { background: linear-gradient(135deg, #ff4757, #d63031); box-shadow: none; }\n.btn.danger:hover { filter: brightness(1.1); }\n.btn.small { padding: 5px 9px; font-size: 11px; }\n.btn.block { width: 100%; }\n\n/* ── Forms ────────────────────────────────────────────────── */\n.input, select.input, textarea.input {\n  width: 100%;\n  background: var(--card);\n  border: 1px solid var(--border);\n  color: var(--text);\n  border-radius: 5px;\n  padding: 10px 12px;\n  font-family: var(--ui);\n  font-size: 14px;\n  transition: border-color 0.12s, box-shadow 0.12s;\n}\n.input:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--red-faint); }\n.input::placeholder { color: var(--muted); }\n\n.field { margin-bottom: 16px; }\n.field label { display: block; margin-bottom: 6px; color: var(--muted); font-size: 12px; letter-spacing: 0.5px; }\n\n/* ── Cards ────────────────────────────────────────────────── */\n.card {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 20px;\n  transition: border-color 0.12s;\n}\n.card + .card { margin-top: 16px; }\n\n.grid { display: grid; gap: 16px; }\n.grid.cols-2 { grid-template-columns: repeat(2, 1fr); }\n.grid.cols-3 { grid-template-columns: repeat(3, 1fr); }\n.grid.cols-4 { grid-template-columns: repeat(4, 1fr); }\n@media (max-width: 900px) { .grid.cols-2, .grid.cols-3, .grid.cols-4 { grid-template-columns: 1fr; } }\n@media (max-width: 1200px) and (min-width: 901px) { .grid.cols-4 { grid-template-columns: repeat(2, 1fr); } }\n\n/* ── Auth ─────────────────────────────────────────────────── */\n.auth-wrap {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n}\n.auth-card {\n  width: 100%;\n  max-width: 400px;\n  border-top: 3px solid var(--brand);\n}\n.auth-tabs { display: flex; margin-bottom: 20px; border-bottom: 1px solid var(--border); }\n.auth-tabs button {\n  flex: 1; background: none; border: none; color: var(--muted);\n  font-family: var(--mono); font-size: 12px; padding: 12px 0;\n  cursor: pointer; border-bottom: 2px solid transparent;\n}\n.auth-tabs button.active { color: var(--red-soft); border-bottom-color: var(--brand); }\n.auth-err { color: var(--danger); font-size: 12px; margin-top: 10px; min-height: 16px; }\n\n/* ── Status badges ────────────────────────────────────────── */\n.badge {\n  display: inline-block;\n  padding: 3px 9px;\n  border-radius: 999px;\n  font-family: var(--mono);\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n  border: 1px solid var(--border);\n  color: var(--muted);\n}\n.badge.uploaded   { color: var(--red-soft); border-color: var(--red-soft); }\n.badge.queued     { color: #ffc46b; border-color: #ffc46b; }\n.badge.processing { color: #ff5c5c; border-color: #ff5c5c; }\n.badge.completed  { color: #ff8a8a; border-color: var(--brand); }\n.badge.failed     { color: var(--danger); border-color: var(--danger); }\n.badge.cancelled  { color: var(--muted); }\n\n/* ── Upload area ──────────────────────────────────────────── */\n.dropzone {\n  border: 2px dashed var(--border);\n  border-radius: 8px;\n  padding: 40px 20px;\n  text-align: center;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s;\n}\n.dropzone:hover, .dropzone.dragover { border-color: var(--brand); background: var(--red-faint); }\n.dropzone .dz-title { font-family: var(--mono); font-size: 15px; color: var(--text); }\n.dropzone .dz-sub { color: var(--muted); font-size: 12px; margin-top: 6px; }\n\n/* ── Progress ─────────────────────────────────────────────── */\n.progress {\n  height: 6px;\n  background: var(--border);\n  border-radius: 999px;\n  overflow: hidden;\n  margin-top: 8px;\n}\n.progress > span {\n  display: block; height: 100%;\n  background: linear-gradient(90deg, var(--brand) 0%, var(--brand-dark) 100%);\n  box-shadow: 0 0 10px var(--red-glow);\n  width: 0%;\n  transition: width 0.2s;\n}\n.progress-bar-label { font-family: var(--mono); font-size: 11px; color: var(--muted); margin-top: 6px; }\n\n/* ── Tables ───────────────────────────────────────────────── */\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 11px 12px; border-bottom: 1px solid var(--border); font-size: 13px; }\nth { color: var(--muted); font-family: var(--mono); font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; }\ntr:hover td { background: var(--surface); }\ntd .mono { font-size: 12px; }\n\n/* ── Toolbar ──────────────────────────────────────────────── */\n.toolbar { display: flex; align-items: center; gap: 8px; margin-bottom: 18px; flex-wrap: wrap; }\n.toolbar .spacer { flex: 1; }\n\n/* ── Gallery ──────────────────────────────────────────────── */\n.gallery {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));\n  gap: 12px;\n}\n.frame-card {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  overflow: hidden;\n  cursor: pointer;\n  transition: border-color 0.12s, transform 0.12s, box-shadow 0.12s;\n}\n.frame-card:hover { border-color: var(--brand); transform: translateY(-2px); box-shadow: 0 6px 18px var(--red-glow); }\n.frame-card.selected { border-color: var(--brand); border-width: 2px; box-shadow: 0 0 0 1px var(--brand); }\n.frame-card img { width: 100%; display: block; aspect-ratio: 16 / 9; object-fit: cover; background: #000; }\n.chunk-card .chunk-video { width: 100%; display: block; aspect-ratio: 16 / 9; background: #000; }\n.chunk-card .chunk-video::-webkit-media-controls-panel { background: #0a0a0c; }\n.frame-card .fc-bar {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 6px 8px; background: var(--surface);\n  font-family: var(--mono); font-size: 11px; color: var(--muted);\n}\n.frame-card .fc-bar .fc-check { accent-color: var(--brand); }\n\n.pager { display: flex; align-items: center; gap: 12px; margin-top: 18px; }\n.pager .pager-info { font-family: var(--mono); font-size: 12px; color: var(--muted); }\n\n/* ── Modal / Preview ──────────────────────────────────────── */\n.modal-backdrop {\n  position: fixed; inset: 0; background: rgba(0,0,0,0.8);\n  display: flex; align-items: center; justify-content: center; z-index: 50;\n  padding: 20px;\n}\n.modal {\n  background: var(--surface); border: 1px solid var(--border); border-radius: 10px;\n  border-top: 3px solid var(--brand);\n  max-width: 940px; width: 100%; max-height: 92vh; overflow: hidden;\n  display: flex; flex-direction: column;\n}\n.modal-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px; border-bottom: 1px solid var(--border); }\n.modal-body { padding: 18px; overflow-y: auto; }\n.modal-footer { display: flex; gap: 8px; padding: 14px 18px; border-top: 1px solid var(--border); align-items: center; flex-wrap: wrap; }\n\n.preview-img-wrap { display: flex; align-items: center; justify-content: center; background: #000; border-radius: 6px; overflow: hidden; min-height: 320px; }\n.preview-img-wrap img { max-width: 100%; max-height: 60vh; }\n\n/* ── Misc ─────────────────────────────────────────────────── */\n.stat {\n  font-family: var(--mono);\n  font-size: 26px;\n  margin-top: 4px;\n  background: linear-gradient(120deg, var(--red-soft) 0%, var(--brand) 60%, var(--brand-dark) 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n.pill {\n  display: inline-block; padding: 2px 8px; border-radius: 999px;\n  background: var(--border); font-family: var(--mono); font-size: 11px; color: var(--text);\n}\n.spinner {\n  width: 22px; height: 22px; border: 3px solid var(--border);\n  border-top-color: var(--brand); border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n}\n@keyframes spin { to { transform: rotate(360deg); } }\n.empty-state { text-align: center; color: var(--muted); padding: 60px 20px; font-size: 14px; }\n\n.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }\n.gap-8 { gap: 8px; }\n.grow { flex: 1; }\n.mt-12 { margin-top: 12px; }\n.mt-20 { margin-top: 20px; }\n.mb-20 { margin-bottom: 20px; }\n\ninput[type=\"range\"] { accent-color: var(--brand); }\n\n/* ── Stat cards ──────────────────────────────────────────── */\n.stat-card {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 18px 20px;\n  position: relative;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  transition: border-color 0.12s, transform 0.12s;\n}\n.stat-card::after {\n  content: \"\";\n  position: absolute;\n  top: 0; left: 0; right: 0;\n  height: 3px;\n  background: linear-gradient(90deg, var(--brand), var(--brand-dark));\n}\n.stat-card:hover { border-color: var(--brand); transform: translateY(-2px); }\n.stat-card .stat-label {\n  font-family: var(--mono);\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  color: var(--muted);\n  display: flex;\n  align-items: center;\n  gap: 7px;\n}\n.stat-card .stat-label .dot {\n  width: 8px; height: 8px; border-radius: 50%; display: inline-block;\n}\n.stat-card .stat-label .dot.dot-brand { background: var(--brand); box-shadow: 0 0 8px var(--red-glow); }\n.stat-card .stat-label .dot.dot-warn { background: #ffc46b; }\n.stat-card .stat-label .dot.dot-ok { background: #22c55e; }\n.stat-card .stat-label .dot.dot-soft { background: var(--muted); }\n.stat-card .stat-value {\n  font-family: var(--mono);\n  font-size: 28px;\n  font-weight: 700;\n  line-height: 1;\n  background: linear-gradient(120deg, var(--red-soft), var(--brand) 60%, var(--brand-dark));\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n.stat-card .stat-sub { font-size: 12px; color: var(--muted); }\n\n/* ── Card header / meta grid ─────────────────────────────── */\n.card-header { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }\n.card-header h3 { margin: 0; }\n.card-header .spacer { flex: 1; }\n.divider { height: 1px; background: var(--border); margin: 14px 0; }\n\n.meta-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));\n  gap: 14px 22px;\n}\n.meta-grid > div h3 { margin-bottom: 4px; }\n.meta-grid > div .meta-val {\n  font-family: var(--mono);\n  font-size: 13px;\n  word-break: break-word;\n  color: var(--text);\n}\n\n/* ── Toasts ──────────────────────────────────────────────── */\n.toast-wrap {\n  position: fixed;\n  bottom: 20px; right: 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 100;\n}\n.toast {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-left: 3px solid var(--brand);\n  border-radius: 6px;\n  padding: 12px 16px;\n  min-width: 240px;\n  max-width: 380px;\n  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);\n  font-size: 13px;\n  animation: toast-in 0.18s ease-out;\n}\n.toast.ok { border-left-color: #22c55e; }\n.toast.err { border-left-color: var(--danger); }\n@keyframes toast-in { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: none; } }\n\n/* ── Loading skeleton ────────────────────────────────────── */\n.skeleton {\n  position: relative;\n  overflow: hidden;\n  background: var(--border);\n  border-radius: 5px;\n}\n.skeleton::after {\n  content: \"\";\n  position: absolute; inset: 0;\n  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.06), transparent);\n  animation: shimmer 1.2s infinite;\n}\n@keyframes shimmer { from { transform: translateX(-100%); } to { transform: translateX(100%); } }\ntr.loading td { color: var(--muted); font-style: italic; }\n\n/* ── Empty states with CTA ───────────────────────────────── */\n.empty-state .empty-icon { font-size: 34px; margin-bottom: 8px; opacity: 0.45; }\n.empty-state .empty-cta { margin-top: 14px; display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }\n\n/* ── Chunk cards ─────────────────────────────────────────── */\n.chunk-meta {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 6px 8px;\n  background: var(--surface);\n  border-top: 1px solid var(--border);\n  font-family: var(--mono);\n  font-size: 11px;\n  color: var(--muted);\n}\n.chunk-meta .chip {\n  padding: 1px 7px;\n  border-radius: 999px;\n  background: var(--red-faint);\n  border: 1px solid var(--brand);\n  color: var(--red-soft);\n  font-size: 10px;\n}\n\n/* ── Table scroll + sticky header ────────────────────────── */\n.table-scroll { max-height: 70vh; overflow-y: auto; }\n.table-scroll thead th { position: sticky; top: 0; background: var(--surface); z-index: 1; }\n\n/* ── Small helpers ───────────────────────────────────────── */\n.toolbar .toolbar-note { color: var(--muted); font-size: 12px; }\n.mono-num { font-variant-numeric: tabular-nums; }\n";

export const apiJs: string = "/* Shared API client for the KENDUIT portals. */\nwindow.API = (() => {\n  const TOKEN_KEY = \"frameforge_token\";\n  const USER_KEY = \"frameforge_user\";\n\n  const token = () => localStorage.getItem(TOKEN_KEY);\n  const setToken = (t) => localStorage.setItem(TOKEN_KEY, t);\n  const clearToken = () => localStorage.removeItem(TOKEN_KEY);\n\n  const getUser = () => {\n    try { return JSON.parse(localStorage.getItem(USER_KEY) || \"null\"); }\n    catch { return null; }\n  };\n  const setUser = (u) => localStorage.setItem(USER_KEY, JSON.stringify(u));\n\n  async function request(path, { method = \"GET\", body, auth = true } = {}) {\n    const headers = { \"Content-Type\": \"application/json\" };\n    if (auth && token()) headers[\"Authorization\"] = `Bearer ${token()}`;\n    const res = await fetch(path, { method, headers, body: body ? JSON.stringify(body) : undefined });\n    const data = await res.json().catch(() => ({}));\n    if (!res.ok) {\n      const err = new Error(data.error || `Request failed (${res.status})`);\n      err.status = res.status;\n      err.code = data.code;\n      throw err;\n    }\n    return data;\n  }\n\n  async function login(email, password) {\n    const data = await request(\"/api/auth/login\", { method: \"POST\", body: { email, password }, auth: false });\n    setToken(data.token);\n    setUser(data.user);\n    return data.user;\n  }\n\n  async function register(email, password) {\n    const data = await request(\"/api/auth/register\", { method: \"POST\", body: { email, password }, auth: false });\n    setToken(data.token);\n    setUser(data.user);\n    return data.user;\n  }\n\n  function logout() { clearToken(); localStorage.removeItem(USER_KEY); }\n\n  /**\n   * Upload a File in multipart parts, relayed through the Worker.\n   * Each part is PUT same-origin to /api/uploads/part/:jobId/:partNumber,\n   * which forwards it into the R2 multipart upload. This avoids needing a CORS\n   * policy on the R2 bucket (direct browser→R2 PUTs are blocked without one).\n   */\n  async function uploadVideo(file, onProgress) {\n    const createRes = await request(\"/api/uploads/create\", {\n      method: \"POST\",\n      body: { filename: file.name, size: file.size, mimeType: file.type || \"video/mp4\" },\n    });\n    const { jobId, uploadId, chunkSize } = createRes;\n\n    const etags = [];\n    let uploadedBytes = 0;\n    const partCount = Math.max(1, Math.ceil(file.size / chunkSize));\n    for (let partNumber = 1; partNumber <= partCount; partNumber++) {\n      const start = (partNumber - 1) * chunkSize;\n      const end = Math.min(start + chunkSize, file.size);\n      const blob = file.slice(start, end);\n      const resp = await fetch(`/api/uploads/part/${jobId}/${partNumber}`, {\n        method: \"PUT\",\n        headers: { Authorization: `Bearer ${token()}`, \"X-Upload-Id\": uploadId },\n        body: blob,\n      });\n      const data = await resp.json().catch(() => ({}));\n      if (!resp.ok) {\n        throw new Error(`Part ${partNumber} failed (${resp.status})${data.error ? `: ${data.error}` : \"\"}`);\n      }\n      if (!data.etag) throw new Error(`Part ${partNumber} returned no ETag`);\n      etags.push({ partNumber, etag: data.etag });\n      uploadedBytes += blob.size;\n      if (onProgress) onProgress(uploadedBytes / file.size);\n    }\n\n    const complete = await request(\"/api/uploads/complete\", {\n      method: \"POST\",\n      body: { jobId, uploadId, parts: etags },\n    });\n    return complete;\n  }\n\n  function fmtBytes(n) {\n    if (!n) return \"0 B\";\n    const units = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\"];\n    let i = 0; let v = n;\n    while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }\n    return `${v.toFixed(v >= 10 || i === 0 ? 0 : 1)} ${units[i]}`;\n  }\n\n  function fmtDuration(secs) {\n    if (!secs && secs !== 0) return \"—\";\n    const m = Math.floor(secs / 60);\n    const s = Math.floor(secs % 60);\n    return `${String(m).padStart(2, \"0\")}:${String(s).padStart(2, \"0\")}`;\n  }\n\n  function fmtTimestamp(ts) {\n    if (ts == null) return \"—\";\n    const m = Math.floor(ts / 60);\n    const s = (ts % 60).toFixed(1);\n    return `${String(m).padStart(2, \"0\")}:${String(s).padStart(2, \"0\").padStart(4, \"0\")}`;\n  }\n\n  function statusLabel(s) {\n    return s ? s[0].toUpperCase() + s.slice(1) : \"—\";\n  }\n\n  return {\n    request, login, register, logout, uploadVideo,\n    token, setToken, clearToken, getUser, setUser,\n    fmtBytes, fmtDuration, fmtTimestamp, statusLabel,\n  };\n})();\n";

export const userJs: string = "/* KENDUIT — user portal logic. */\n(() => {\n  const $ = (id) => document.getElementById(id);\n  const API = window.API;\n\n  const TERMINAL = [\"completed\", \"failed\", \"cancelled\"];\n  let polling = false;\n  let selectedFile = null;\n\n  const viewAuth = $(\"view-auth\");\n  const viewApp = $(\"view-app\");\n  const authErr = $(\"auth-err\");\n  const authSubmit = $(\"auth-submit\");\n  let authMode = \"login\";\n\n  function showAuth() { viewAuth.classList.remove(\"hidden\"); viewApp.classList.add(\"hidden\"); }\n  function showApp() { viewAuth.classList.add(\"hidden\"); viewApp.classList.remove(\"hidden\"); }\n\n  function setAuthTab(mode) {\n    authMode = mode;\n    $(\"tab-login\").classList.toggle(\"active\", mode === \"login\");\n    $(\"tab-register\").classList.toggle(\"active\", mode === \"register\");\n    $(\"auth-submit\").textContent = mode === \"login\" ? \"Login\" : \"Create account\";\n    $(\"auth-password\").autocomplete = mode === \"login\" ? \"current-password\" : \"new-password\";\n    authErr.textContent = \"\";\n  }\n\n  $(\"tab-login\").addEventListener(\"click\", () => setAuthTab(\"login\"));\n  $(\"tab-register\").addEventListener(\"click\", () => setAuthTab(\"register\"));\n\n  $(\"auth-form\").addEventListener(\"submit\", async (e) => {\n    e.preventDefault();\n    const email = $(\"auth-email\").value.trim();\n    const password = $(\"auth-password\").value;\n    authSubmit.disabled = true;\n    authErr.textContent = \"\";\n    try {\n      if (authMode === \"login\") await API.login(email, password);\n      else await API.register(email, password);\n      enterApp();\n    } catch (err) {\n      authErr.textContent = err.message;\n    } finally {\n      authSubmit.disabled = false;\n    }\n  });\n\n  function enterApp() {\n    const u = API.getUser();\n    $(\"user-email\").textContent = u ? u.email : \"\";\n    showApp();\n    loadVideos();\n  }\n\n  $(\"btn-logout\").addEventListener(\"click\", () => {\n    API.logout();\n    stopPolling();\n    showAuth();\n  });\n\n  // Sidebar \"My Videos\" — refresh the list when clicked.\n  document.querySelectorAll(\".nav a\").forEach((a) => {\n    a.addEventListener(\"click\", (e) => {\n      e.preventDefault();\n      document.querySelectorAll(\".nav a\").forEach((x) => x.classList.remove(\"active\"));\n      a.classList.add(\"active\");\n      loadVideos();\n    });\n  });\n\n  // ── Upload ────────────────────────────────────────────────\n  const dropzone = $(\"dropzone\");\n  const fileInput = $(\"file-input\");\n\n  dropzone.addEventListener(\"click\", () => fileInput.click());\n  dropzone.addEventListener(\"dragover\", (e) => { e.preventDefault(); dropzone.classList.add(\"dragover\"); });\n  dropzone.addEventListener(\"dragleave\", () => dropzone.classList.remove(\"dragover\"));\n  dropzone.addEventListener(\"drop\", (e) => {\n    e.preventDefault();\n    dropzone.classList.remove(\"dragover\");\n    if (e.dataTransfer.files.length) startUpload(e.dataTransfer.files[0]);\n  });\n  fileInput.addEventListener(\"change\", () => {\n    if (fileInput.files.length) startUpload(fileInput.files[0]);\n  });\n\n  $(\"btn-upload\").addEventListener(\"click\", () => $(\"upload-panel\").classList.toggle(\"hidden\"));\n\n  async function startUpload(file) {\n    selectedFile = file;\n    $(\"upload-panel\").classList.remove(\"hidden\");\n    $(\"upload-progress-wrap\").classList.remove(\"hidden\");\n    $(\"upload-err\").textContent = \"\";\n    $(\"upload-progress-bar\").style.width = \"0%\";\n    $(\"upload-progress-label\").textContent = `Uploading ${file.name} (${API.fmtBytes(file.size)})… 0%`;\n\n    try {\n      await API.uploadVideo(file, (pct) => {\n        const p = Math.round(pct * 100);\n        $(\"upload-progress-bar\").style.width = p + \"%\";\n        $(\"upload-progress-label\").textContent = `Uploading ${file.name} — ${p}%`;\n      });\n      $(\"upload-progress-label\").textContent = \"Upload complete — video is waiting for processing.\";\n      fileInput.value = \"\";\n      await loadVideos();\n      toast(\"Upload complete — your video is queued.\");\n    } catch (err) {\n      $(\"upload-err\").textContent = \"Upload failed: \" + err.message;\n    }\n  }\n\n  function toast(msg, type = \"ok\") {\n    const wrap = $(\"toast-wrap\");\n    if (!wrap) return;\n    const el = document.createElement(\"div\");\n    el.className = \"toast \" + type;\n    el.textContent = msg;\n    wrap.appendChild(el);\n    setTimeout(() => {\n      el.style.transition = \"opacity .3s\";\n      el.style.opacity = \"0\";\n      setTimeout(() => el.remove(), 350);\n    }, 3400);\n  }\n\n  $(\"empty-upload\").addEventListener(\"click\", () => $(\"upload-panel\").classList.remove(\"hidden\"));\n\n  // ── Videos list ───────────────────────────────────────────\n  async function loadVideos() {\n    try {\n      const data = await API.request(\"/api/videos\");\n      renderVideos(data.jobs || []);\n      const hasLive = (data.jobs || []).some((j) => !TERMINAL.includes(j.status));\n      if (hasLive) startPolling(); else stopPolling();\n    } catch (err) {\n      if (err.status === 401) { API.logout(); showAuth(); }\n    }\n  }\n\n  function renderVideos(jobs) {\n    $(\"videos-empty\").classList.toggle(\"hidden\", jobs.length > 0);\n    $(\"videos-table\").classList.toggle(\"hidden\", jobs.length === 0);\n    const framesTotal = jobs.reduce((a, j) => a + (j.extracted_frames || 0), 0);\n    const chunksTotal = jobs.reduce((a, j) => a + (j.chunk_count || 0), 0);\n    $(\"library-note\").textContent = jobs.length\n      ? `${jobs.length} video${jobs.length === 1 ? \"\" : \"s\"} · ${framesTotal} frame${framesTotal === 1 ? \"\" : \"s\"} · ${chunksTotal} chunk${chunksTotal === 1 ? \"\" : \"s\"}`\n      : \"—\";\n    const body = $(\"videos-body\");\n    body.innerHTML = \"\";\n    for (const j of jobs) {\n      const tr = document.createElement(\"tr\");\n      tr.innerHTML = `\n        <td class=\"mono\">${escapeHtml(j.original_filename)}</td>\n        <td>${API.fmtBytes(j.file_size)}</td>\n        <td class=\"mono\">${API.fmtDuration(j.duration)}</td>\n        <td class=\"mono small muted\">${new Date(j.created_at).toLocaleString()}</td>\n        <td class=\"mono\">${j.extracted_frames || 0}</td>\n        <td>${renderChunkCell(j)}</td>\n        <td><span class=\"badge ${j.status}\">${API.statusLabel(j.status)}</span></td>`;\n      body.appendChild(tr);\n    }\n  }\n\n  function renderChunkCell(j) {\n    if (!j.chunk_status || j.chunk_status === \"none\") return '<span class=\"muted small\">—</span>';\n    const cls = j.chunk_status === \"completed\" ? \"completed\" : j.chunk_status === \"failed\" ? \"failed\" : \"queued\";\n    const label = j.chunk_status === \"completed\"\n      ? (j.chunk_count ? `${j.chunk_count} chunks` : \"done\")\n      : API.statusLabel(j.chunk_status);\n    return `<span class=\"badge ${cls}\">${label}</span>`;\n  }\n\n  function startPolling() {\n    if (polling) return;\n    polling = true;\n    window.setInterval(() => { if (polling) loadVideos(); }, 8000);\n  }\n  function stopPolling() { polling = false; }\n\n  function escapeHtml(s) {\n    const d = document.createElement(\"div\");\n    d.textContent = s == null ? \"\" : String(s);\n    return d.innerHTML;\n  }\n\n  // ── Init ──────────────────────────────────────────────────\n  if (API.token()) enterApp();\n  else showAuth();\n})();\n";

export const adminJs: string = "/* KENDUIT — admin portal logic. */\n(() => {\n  const $ = (id) => document.getElementById(id);\n  const API = window.API;\n\n  const TERMINAL = [\"completed\", \"failed\", \"cancelled\"];\n  const state = {\n    filter: \"all\",\n    jobsPage: 1,\n    jobsPerPage: 20,\n    jobsTotal: 0,\n    search: \"\",\n    job: null,\n    frames: [],\n    framesPage: 1,\n    framesPerPage: 50,\n    framesTotal: 0,\n    selected: new Set(),\n    chunks: [],\n    chunksPage: 1,\n    chunksPerPage: 30,\n    chunksTotal: 0,\n    selectedChunks: new Set(),\n    exportId: null,\n    exportTimer: null,\n    jobTimer: null,\n  };\n\n  // ── Auth ──────────────────────────────────────────────────\n  $(\"auth-form\").addEventListener(\"submit\", async (e) => {\n    e.preventDefault();\n    const email = $(\"auth-email\").value.trim();\n    const password = $(\"auth-password\").value;\n    $(\"auth-submit\").disabled = true;\n    $(\"auth-err\").textContent = \"\";\n    try {\n      const user = await API.login(email, password);\n      if (user.role !== \"admin\") {\n        API.logout();\n        $(\"auth-err\").textContent = \"This account is not an administrator.\";\n        return;\n      }\n      enterApp();\n    } catch (err) {\n      $(\"auth-err\").textContent = err.message;\n    } finally {\n      $(\"auth-submit\").disabled = false;\n    }\n  });\n\n  $(\"btn-logout\").addEventListener(\"click\", () => {\n    API.logout();\n    stopAllTimers();\n    showAuth();\n  });\n\n  function showAuth() { $(\"view-auth\").classList.remove(\"hidden\"); $(\"view-app\").classList.add(\"hidden\"); }\n  function enterApp() {\n    const u = API.getUser();\n    $(\"user-email\").textContent = u ? u.email : \"\";\n    $(\"view-auth\").classList.add(\"hidden\");\n    $(\"view-app\").classList.remove(\"hidden\");\n    loadStats();\n    loadJobs();\n  }\n\n  // ── Sidebar / filters ─────────────────────────────────────\n  document.querySelectorAll(\".nav a\").forEach((a) => {\n    a.addEventListener(\"click\", (e) => {\n      e.preventDefault();\n      // Navigating from a job detail back to the list: stop timers, clear the\n      // job, and swap back to the videos view so the click is always visible.\n      stopAllTimers();\n      state.job = null;\n      document.querySelectorAll(\".nav a\").forEach((x) => x.classList.remove(\"active\"));\n      a.classList.add(\"active\");\n      state.filter = a.dataset.filter;\n      state.jobsPage = 1;\n      $(\"view-title\").textContent = a.textContent;\n      $(\"view-job\").classList.add(\"hidden\");\n      $(\"view-videos\").classList.remove(\"hidden\");\n      loadJobs();\n      loadStats();\n    });\n  });\n\n  let searchTimer = null;\n  $(\"search-input\").addEventListener(\"input\", () => {\n    clearTimeout(searchTimer);\n    searchTimer = setTimeout(() => {\n      state.search = $(\"search-input\").value.trim();\n      state.jobsPage = 1;\n      loadJobs();\n    }, 350);\n  });\n\n  $(\"prev-page\").addEventListener(\"click\", () => { if (state.jobsPage > 1) { state.jobsPage--; loadJobs(); } });\n  $(\"next-page\").addEventListener(\"click\", () => { if (state.jobsPage * state.jobsPerPage < state.jobsTotal) { state.jobsPage++; loadJobs(); } });\n\n  // ── Stats ─────────────────────────────────────────────────\n  async function loadStats() {\n    try {\n      const data = await API.request(\"/api/admin/stats\");\n      const s = data.stats || {};\n      const total = Object.values(s).reduce((a, b) => a + (Number(b) || 0), 0);\n      $(\"stat-uploaded\").textContent = s.uploaded ?? 0;\n      $(\"stat-queued\").textContent = (s.queued ?? 0) + (s.processing ?? 0);\n      $(\"stat-completed\").textContent = s.completed ?? 0;\n      $(\"stat-total\").textContent = total;\n    } catch (err) { /* non-fatal */ }\n  }\n\n  // ── Jobs table ────────────────────────────────────────────\n  async function loadJobs() {\n    const q = new URLSearchParams({ page: state.jobsPage, perPage: state.jobsPerPage });\n    if (state.filter !== \"all\") q.set(\"status\", state.filter);\n    if (state.search) q.set(\"search\", state.search);\n    const body = $(\"jobs-body\");\n    body.innerHTML = `<tr class=\"loading\"><td colspan=\"10\">Loading jobs…</td></tr>`;\n    $(\"jobs-empty\").classList.add(\"hidden\");\n    $(\"jobs-table\").classList.remove(\"hidden\");\n    try {\n      const data = await API.request(`/api/admin/videos?${q}`);\n      state.jobsTotal = data.total;\n      renderJobs(data.jobs || []);\n    } catch (err) {\n      if (err.status === 401) { API.logout(); showAuth(); }\n    }\n  }\n\n  function renderJobs(jobs) {\n    $(\"jobs-empty\").classList.toggle(\"hidden\", jobs.length > 0);\n    $(\"jobs-table\").classList.toggle(\"hidden\", jobs.length === 0);\n    const body = $(\"jobs-body\");\n    body.innerHTML = \"\";\n    for (const j of jobs) {\n      const tr = document.createElement(\"tr\");\n      tr.innerHTML = `\n        <td class=\"small muted\">${esc(j.user_email)}</td>\n        <td class=\"mono\">${esc(j.original_filename)}</td>\n        <td>${API.fmtBytes(j.file_size)}</td>\n        <td class=\"mono\">${API.fmtDuration(j.duration)}</td>\n        <td class=\"mono\">${j.width && j.height ? `${j.width}x${j.height}` : \"—\"}</td>\n        <td class=\"mono small muted\">${new Date(j.created_at).toLocaleString()}</td>\n        <td><span class=\"badge ${j.status}\">${API.statusLabel(j.status)}</span></td>\n        <td class=\"mono\">${j.extracted_frames}</td>\n        <td>${renderChunkCell(j)}</td>\n        <td>\n          <div class=\"row gap-8\">\n            <button class=\"btn ghost small act-view\" data-id=\"${j.id}\">View</button>\n            ${[\"uploaded\", \"failed\", \"cancelled\"].includes(j.status) ? `<button class=\"btn small act-process\" data-id=\"${j.id}\">Process</button>` : \"\"}\n            ${j.status === \"failed\" ? `<button class=\"btn ghost small act-retry\" data-id=\"${j.id}\">Retry</button>` : \"\"}\n            <button class=\"btn danger small act-delete\" data-id=\"${j.id}\">Delete</button>\n          </div>\n        </td>`;\n      body.appendChild(tr);\n    }\n    body.querySelectorAll(\".act-view\").forEach((b) => b.addEventListener(\"click\", () => openJob(b.dataset.id)));\n    body.querySelectorAll(\".act-process\").forEach((b) => b.addEventListener(\"click\", () => openJob(b.dataset.id)));\n    body.querySelectorAll(\".act-retry\").forEach((b) => b.addEventListener(\"click\", () => retryJob(b.dataset.id)));\n    body.querySelectorAll(\".act-delete\").forEach((b) => b.addEventListener(\"click\", () => deleteJob(b.dataset.id)));\n    $(\"page-info\").textContent = `Page ${state.jobsPage} of ${Math.max(1, Math.ceil(state.jobsTotal / state.jobsPerPage))}`;\n  }\n\n  function renderChunkCell(j) {\n    if (!j.chunk_status || j.chunk_status === \"none\") return '<span class=\"muted small\">—</span>';\n    const cls = j.chunk_status === \"completed\" ? \"completed\" : j.chunk_status === \"failed\" ? \"failed\" : \"queued\";\n    const label = j.chunk_status === \"completed\"\n      ? (j.chunk_count ? `${j.chunk_count} chunks` : \"done\")\n      : API.statusLabel(j.chunk_status);\n    return `<span class=\"badge ${cls}\">${label}</span>`;\n  }\n\n  // ── Job detail ────────────────────────────────────────────\n  $(\"back-btn\").addEventListener(\"click\", () => {\n    stopAllTimers();\n    state.job = null;\n    $(\"view-job\").classList.add(\"hidden\");\n    $(\"view-videos\").classList.remove(\"hidden\");\n    loadJobs();\n    loadStats();\n  });\n\n  $(\"mode-select\").addEventListener(\"change\", () => {\n    $(\"custom-fps-wrap\").classList.toggle(\"hidden\", $(\"mode-select\").value !== \"Custom FPS\");\n  });\n  $(\"sharpness\").addEventListener(\"input\", () => { $(\"sharp-val\").textContent = $(\"sharpness\").value; });\n  $(\"scene-threshold\").addEventListener(\"input\", () => { $(\"scene-val\").textContent = $(\"scene-threshold\").value; });\n  $(\"start-process\").addEventListener(\"click\", startProcess);\n\n  async function openJob(id) {\n    stopAllTimers();\n    try {\n      const data = await API.request(`/api/jobs/${id}`);\n      state.job = data.job;\n      $(\"view-videos\").classList.add(\"hidden\");\n      $(\"view-job\").classList.remove(\"hidden\");\n      renderJob();\n    } catch (err) {\n      alert(\"Failed to open job: \" + err.message);\n    }\n  }\n\n  function renderJob() {\n    const j = state.job;\n    $(\"job-title\").textContent = j.original_filename;\n    const b = $(\"job-status-badge\");\n    b.className = \"badge \" + j.status;\n    b.textContent = API.statusLabel(j.status);\n    $(\"job-err\").textContent = \"\";\n\n    const meta = [\n      [\"User\", j.user_email || \"—\"],\n      [\"Size\", API.fmtBytes(j.file_size)],\n      [\"Duration\", API.fmtDuration(j.duration)],\n      [\"Resolution\", j.width && j.height ? `${j.width}x${j.height}` : \"—\"],\n      [\"Source FPS\", j.source_fps ? j.source_fps.toFixed(2) : \"—\"],\n      [\"Total frames\", j.total_source_frames ? `${j.total_source_frames} source` : \"—\"],\n      [\"Extracted\", `${j.extracted_frames} frames`],\n      [\"Chunks\", j.chunk_count ? `${j.chunk_count} split` : \"—\"],\n    ];\n    if (j.error_message) meta.push([\"Error\", j.error_message]);\n    if (j.chunk_error) meta.push([\"Chunk Error\", j.chunk_error]);\n    $(\"job-meta\").innerHTML = meta.map(([k, v]) => `<div><h3>${esc(k)}</h3><div class=\"meta-val\">${esc(v)}</div></div>`).join(\"\");\n\n    // Chunk status badge\n    const csb = $(\"chunk-status-badge\");\n    csb.className = \"badge \" + (j.chunk_status === \"completed\" ? \"completed\" : j.chunk_status === \"failed\" ? \"failed\" : j.chunk_status === \"processing\" || j.chunk_status === \"queued\" ? \"queued\" : \"cancelled\");\n    csb.textContent = j.chunk_status === \"none\" ? \"Not split\" : \"Chunks: \" + API.statusLabel(j.chunk_status);\n\n    // Actions\n    const actions = $(\"job-actions\");\n    actions.innerHTML = \"\";\n    if (j.status === \"queued\" || j.status === \"processing\") {\n      addBtn(actions, \"Cancel\", \"danger\", cancelJob);\n    }\n    if (j.status === \"failed\" || j.status === \"cancelled\") {\n      addBtn(actions, \"Retry\", \"ghost\", retryCurrent);\n    }\n    if (j.status === \"completed\" || j.status === \"failed\") {\n      addBtn(actions, \"Delete\", \"danger\", () => deleteJob(j.id));\n    }\n    if (![\"queued\", \"processing\"].includes(j.status) && ![\"queued\", \"processing\"].includes(j.chunk_status)) {\n      addBtn(actions, \"Split into Chunks\", \"\", splitChunks);\n    }\n\n    // Panels visibility\n    $(\"process-panel\").classList.toggle(\"hidden\", ![\"uploaded\", \"failed\", \"cancelled\"].includes(j.status));\n    const frameActive = [\"queued\", \"processing\"].includes(j.status);\n    const chunkActive = [\"queued\", \"processing\"].includes(j.chunk_status);\n    $(\"progress-panel\").classList.toggle(\"hidden\", !(frameActive || chunkActive));\n    $(\"gallery-panel\").classList.toggle(\"hidden\", ![\"completed\", \"processing\", \"queued\"].includes(j.status));\n    $(\"chunks-panel\").classList.remove(\"hidden\");\n\n    if (j.status === \"queued\" || j.status === \"processing\") {\n      state.framesPage = 1;\n      loadFrames();\n      startJobPolling();\n    } else if (j.status === \"completed\") {\n      state.framesPage = 1;\n      loadFrames();\n    }\n    if ([\"completed\", \"failed\"].includes(j.chunk_status) || [\"queued\", \"processing\"].includes(j.chunk_status)) {\n      state.chunksPage = 1;\n      loadChunks();\n    } else {\n      state.chunks = [];\n      state.chunksTotal = 0;\n      state.selectedChunks.clear();\n      renderChunkGallery();\n    }\n    if (j.chunk_status === \"queued\" || j.chunk_status === \"processing\") {\n      startJobPolling();\n    }\n    updateProgress(j);\n  }\n\n  function addBtn(parent, text, cls, onClick) {\n    const btn = document.createElement(\"button\");\n    btn.className = `btn ${cls} small`;\n    btn.type = \"button\";\n    btn.textContent = text;\n    btn.addEventListener(\"click\", onClick);\n    parent.appendChild(btn);\n  }\n\n  function toast(msg, type = \"ok\") {\n    const wrap = $(\"toast-wrap\");\n    if (!wrap) return;\n    const el = document.createElement(\"div\");\n    el.className = \"toast \" + type;\n    el.textContent = msg;\n    wrap.appendChild(el);\n    setTimeout(() => {\n      el.style.transition = \"opacity .3s\";\n      el.style.opacity = \"0\";\n      setTimeout(() => el.remove(), 350);\n    }, 3400);\n  }\n\n  // Empty-state CTA buttons\n  $(\"empty-clear-filter\").addEventListener(\"click\", () => {\n    document.querySelectorAll(\".nav a\").forEach((x) => x.classList.remove(\"active\"));\n    document.querySelector('.nav a[data-filter=\"all\"]').classList.add(\"active\");\n    state.filter = \"all\";\n    state.search = \"\";\n    $(\"search-input\").value = \"\";\n    state.jobsPage = 1;\n    $(\"view-title\").textContent = \"Dashboard\";\n    loadJobs();\n  });\n  $(\"empty-start-process\").addEventListener(\"click\", () => {\n    $(\"process-panel\").scrollIntoView({ behavior: \"smooth\" });\n  });\n  $(\"empty-split\").addEventListener(\"click\", splitChunks);\n\n  // ── Process / cancel / retry / delete ─────────────────────\n  async function startProcess() {\n    const mode = $(\"mode-select\").value;\n    const body = { mode, sharpness: parseFloat($(\"sharpness\").value) };\n    if (mode === \"Custom FPS\") body.fps = parseFloat($(\"custom-fps\").value);\n    if (mode === \"Smart Scene\") body.sceneThreshold = parseFloat($(\"scene-threshold\").value);\n    $(\"job-err\").textContent = \"\";\n    try {\n      const data = await API.request(`/api/jobs/${state.job.id}/process`, { method: \"POST\", body });\n      state.job = data.job;\n      renderJob();\n      toast(\"Processing started — frames will appear as they extract.\");\n    } catch (err) {\n      $(\"job-err\").textContent = \"Failed to start: \" + err.message;\n    }\n  }\n\n  async function cancelJob() {\n    if (!confirm(\"Cancel this job?\")) return;\n    try { state.job = (await API.request(`/api/jobs/${state.job.id}/cancel`, { method: \"POST\" })).job; renderJob(); }\n    catch (err) { $(\"job-err\").textContent = err.message; }\n  }\n  async function retryCurrent() {\n    try { state.job = (await API.request(`/api/jobs/${state.job.id}/retry`, { method: \"POST\" })).job; renderJob(); }\n    catch (err) { $(\"job-err\").textContent = err.message; }\n  }\n  async function retryJob(id) {\n    try { await API.request(`/api/jobs/${id}/retry`, { method: \"POST\" }); loadJobs(); }\n    catch (err) { alert(\"Retry failed: \" + err.message); }\n  }\n  async function deleteJob(id) {\n    if (!confirm(\"Permanently delete this job, its frames and files?\")) return;\n    try {\n      await API.request(`/api/admin/jobs/${id}`, { method: \"DELETE\" });\n      if (state.job && state.job.id === id) { state.job = null; $(\"view-job\").classList.add(\"hidden\"); $(\"view-videos\").classList.remove(\"hidden\"); }\n      loadJobs(); loadStats();\n      toast(\"Job deleted.\", \"err\");\n    } catch (err) { alert(\"Delete failed: \" + err.message); }\n  }\n\n  // ── Job polling (covers frame extraction AND chunk splitting) ─────────────\n  function startJobPolling() {\n    stopJobTimer();\n    state.jobTimer = setInterval(async () => {\n      if (!state.job) return;\n      try {\n        const data = await API.request(`/api/jobs/${state.job.id}`);\n        const prevStatus = state.job.status;\n        const prevChunk = state.job.chunk_status;\n        state.job = data.job;\n        updateProgress(data.job);\n        if (prevStatus !== data.job.status || prevChunk !== data.job.chunk_status) renderJob();\n        const done = TERMINAL.includes(data.job.status) && [\"none\", \"completed\", \"failed\"].includes(data.job.chunk_status);\n        if (done) stopJobTimer();\n      } catch (err) { /* keep polling */ }\n    }, 4000);\n  }\n  function stopJobTimer() { if (state.jobTimer) { clearInterval(state.jobTimer); state.jobTimer = null; } }\n\n  function updateProgress(j) {\n    const frameActive = [\"queued\", \"processing\"].includes(j.status);\n    const chunkActive = [\"queued\", \"processing\"].includes(j.chunk_status);\n\n    $(\"progress-status-badge\").className = \"badge \" + (chunkActive ? j.chunk_status : j.status);\n    $(\"progress-status-badge\").textContent = chunkActive\n      ? \"Chunks: \" + API.statusLabel(j.chunk_status)\n      : API.statusLabel(j.status);\n\n    const fwrap = $(\"progress-bar\").parentElement;\n    fwrap.style.display = frameActive ? \"block\" : \"none\";\n    $(\"progress-label\").style.display = frameActive ? \"block\" : \"none\";\n    if (frameActive) {\n      const total = j.total_source_frames || 1;\n      const pct = Math.min(100, Math.round((j.processed_frames / total) * 100));\n      $(\"progress-bar\").style.width = pct + \"%\";\n      $(\"progress-label\").textContent = `${j.processed_frames} / ${total} frames · ${pct}%`;\n    }\n\n    const cw = $(\"chunk-progress-wrap\");\n    const cl = $(\"chunk-progress-label\");\n    cw.style.display = chunkActive ? \"block\" : \"none\";\n    cl.style.display = chunkActive ? \"block\" : \"none\";\n    if (chunkActive) {\n      const ctotal = j.chunk_total || 1;\n      const cpct = Math.min(100, Math.round(((j.chunk_processed || 0) / ctotal) * 100));\n      $(\"chunk-progress-bar\").style.width = cpct + \"%\";\n      cl.textContent = `Splitting chunks: ${j.chunk_processed || 0} / ${ctotal} · ${cpct}%`;\n    }\n  }\n\n  // ── Frame gallery ─────────────────────────────────────────\n  $(\"gal-prev\").addEventListener(\"click\", () => { if (state.framesPage > 1) { state.framesPage--; loadFrames(); } });\n  $(\"gal-next\").addEventListener(\"click\", () => { if (state.framesPage * state.framesPerPage < state.framesTotal) { state.framesPage++; loadFrames(); } });\n  $(\"select-all\").addEventListener(\"click\", () => {\n    state.selected = new Set(state.frames.map((f) => f.id));\n    renderGallery();\n  });\n  $(\"deselect-all\").addEventListener(\"click\", () => { state.selected.clear(); renderGallery(); });\n  $(\"delete-selected\").addEventListener(\"click\", deleteSelectedFrames);\n  $(\"export-all\").addEventListener(\"click\", () => exportZIP(\"all\"));\n  $(\"export-selected\").addEventListener(\"click\", () => {\n    if (state.selected.size === 0) { alert(\"No frames selected.\"); return; }\n    exportZIP(\"selected\");\n  });\n\n  async function loadFrames() {\n    if (!state.job) return;\n    const q = new URLSearchParams({ page: state.framesPage, perPage: state.framesPerPage });\n    try {\n      const data = await API.request(`/api/jobs/${state.job.id}/frames?${q}`);\n      state.frames = data.frames || [];\n      state.framesTotal = data.total;\n      state.selected = new Set([...state.selected].filter((id) => state.frames.some((f) => f.id === id)));\n      renderGallery();\n    } catch (err) {\n      if (err.status === 401) { API.logout(); showAuth(); }\n    }\n  }\n\n  function renderGallery() {\n    $(\"gallery-empty\").classList.toggle(\"hidden\", state.frames.length > 0);\n    $(\"gallery\").innerHTML = \"\";\n    $(\"sel-count\").textContent = `${state.selected.size} selected`;\n    for (const f of state.frames) {\n      const card = document.createElement(\"div\");\n      card.className = \"frame-card\" + (state.selected.has(f.id) ? \" selected\" : \"\");\n      card.innerHTML = `\n        <img src=\"${f.thumbUrl}\" alt=\"frame\" loading=\"lazy\" />\n        <div class=\"fc-bar\">\n          <span>#${String(f.frame_number).padStart(4, \"0\")} ${API.fmtTimestamp(f.timestamp)}</span>\n          <input type=\"checkbox\" class=\"fc-check\" ${state.selected.has(f.id) ? \"checked\" : \"\"} />\n        </div>`;\n      card.querySelector(\"img\").addEventListener(\"click\", () => openPreview(f.frame_number));\n      card.querySelector(\".fc-check\").addEventListener(\"change\", (e) => {\n        if (e.target.checked) state.selected.add(f.id); else state.selected.delete(f.id);\n        card.classList.toggle(\"selected\", e.target.checked);\n        $(\"sel-count\").textContent = `${state.selected.size} selected`;\n      });\n      $(\"gallery\").appendChild(card);\n    }\n    $(\"gal-info\").textContent = `${state.frames.length} of ${state.framesTotal} frames`;\n  }\n\n  async function deleteSelectedFrames() {\n    if (state.selected.size === 0) { alert(\"No frames selected.\"); return; }\n    if (!confirm(`Delete ${state.selected.size} frame(s)?`)) return;\n    try {\n      await API.request(`/api/jobs/${state.job.id}/frames/delete`, {\n        method: \"POST\",\n        body: { frameIds: [...state.selected] },\n      });\n      state.selected.clear();\n      loadFrames();\n      const jd = await API.request(`/api/jobs/${state.job.id}`);\n      state.job = jd.job;\n      $(\"job-meta\").innerHTML = \"\";\n      toast(\"Frames deleted.\");\n    } catch (err) {\n      alert(\"Delete failed: \" + err.message);\n    }\n  }\n\n  // ── Chunks (scene-based split) ────────────────────────────\n  $(\"chunk-prev\").addEventListener(\"click\", () => { if (state.chunksPage > 1) { state.chunksPage--; loadChunks(); } });\n  $(\"chunk-next\").addEventListener(\"click\", () => { if (state.chunksPage * state.chunksPerPage < state.chunksTotal) { state.chunksPage++; loadChunks(); } });\n  $(\"chunk-select-all\").addEventListener(\"click\", () => {\n    state.selectedChunks = new Set(state.chunks.map((c) => c.id));\n    renderChunkGallery();\n  });\n  $(\"chunk-deselect-all\").addEventListener(\"click\", () => { state.selectedChunks.clear(); renderChunkGallery(); });\n  $(\"chunk-delete-selected\").addEventListener(\"click\", deleteSelectedChunks);\n  $(\"chunk-export-all\").addEventListener(\"click\", () => exportChunks(\"all\"));\n  $(\"chunk-export-selected\").addEventListener(\"click\", () => {\n    if (state.selectedChunks.size === 0) { alert(\"No chunks selected.\"); return; }\n    exportChunks(\"selected\");\n  });\n\n  async function splitChunks() {\n    if (!state.job) return;\n    if (!confirm(\"Split this video into chunks by background change? Existing chunks will be replaced.\")) return;\n    $(\"job-err\").textContent = \"\";\n    try {\n      const data = await API.request(`/api/jobs/${state.job.id}/chunk`, { method: \"POST\" });\n      state.job = data.job;\n      renderJob();\n      toast(\"Scene split started — chunks will appear as they process.\");\n    } catch (err) {\n      $(\"job-err\").textContent = \"Failed to start chunk split: \" + err.message;\n    }\n  }\n\n  async function loadChunks() {\n    if (!state.job) return;\n    const q = new URLSearchParams({ page: state.chunksPage, perPage: state.chunksPerPage });\n    try {\n      const data = await API.request(`/api/jobs/${state.job.id}/chunks?${q}`);\n      state.chunks = data.chunks || [];\n      state.chunksTotal = data.total;\n      state.selectedChunks = new Set([...state.selectedChunks].filter((id) => state.chunks.some((c) => c.id === id)));\n      renderChunkGallery();\n    } catch (err) {\n      if (err.status === 401) { API.logout(); showAuth(); }\n    }\n  }\n\n  function renderChunkGallery() {\n    if (!state.chunks) return;\n    $(\"chunks-empty\").classList.toggle(\"hidden\", state.chunks.length > 0);\n    $(\"chunks-gallery\").innerHTML = \"\";\n    $(\"chunk-sel-count\").textContent = `${state.selectedChunks.size} selected`;\n    for (const c of state.chunks) {\n      const card = document.createElement(\"div\");\n      card.className = \"frame-card chunk-card\" + (state.selectedChunks.has(c.id) ? \" selected\" : \"\");\n      card.innerHTML = `\n        <video class=\"chunk-video\" src=\"${c.playUrl}\" preload=\"metadata\" controls></video>\n        <div class=\"chunk-meta\">\n          <span>#${String(c.chunk_number).padStart(4, \"0\")}</span>\n          <span class=\"chip\">${fmtRange(c.start_sec, c.end_sec)}</span>\n        </div>\n        <div class=\"fc-bar\">\n          <span>${c.duration ? API.fmtDuration(c.duration) : \"—\"}${c.file_size ? \" · \" + API.fmtBytes(c.file_size) : \"\"}</span>\n          <input type=\"checkbox\" class=\"fc-check\" ${state.selectedChunks.has(c.id) ? \"checked\" : \"\"} />\n        </div>`;\n      card.querySelector(\".fc-check\").addEventListener(\"change\", (e) => {\n        if (e.target.checked) state.selectedChunks.add(c.id); else state.selectedChunks.delete(c.id);\n        card.classList.toggle(\"selected\", e.target.checked);\n        $(\"chunk-sel-count\").textContent = `${state.selectedChunks.size} selected`;\n      });\n      $(\"chunks-gallery\").appendChild(card);\n    }\n    $(\"chunk-info\").textContent = `${state.chunks.length} of ${state.chunksTotal} chunks`;\n  }\n\n  function fmtRange(a, b) {\n    return `${API.fmtTimestamp(a)} – ${API.fmtTimestamp(b)}`;\n  }\n\n  async function deleteSelectedChunks() {\n    if (state.selectedChunks.size === 0) { alert(\"No chunks selected.\"); return; }\n    if (!confirm(`Delete ${state.selectedChunks.size} chunk(s)?`)) return;\n    try {\n      await API.request(`/api/jobs/${state.job.id}/chunks/delete`, {\n        method: \"POST\",\n        body: { chunkIds: [...state.selectedChunks] },\n      });\n      state.selectedChunks.clear();\n      loadChunks();\n      toast(\"Chunks deleted.\");\n    } catch (err) {\n      alert(\"Delete failed: \" + err.message);\n    }\n  }\n\n  async function exportChunks(type) {\n    if (!state.job) return;\n    $(\"export-modal\").classList.remove(\"hidden\");\n    $(\"export-footer\").style.display = \"none\";\n    $(\"export-status-row\").classList.remove(\"hidden\");\n    $(\"export-status-text\").textContent = \"Creating ZIP…\";\n    $(\"export-err\").textContent = \"\";\n    try {\n      const body = { type };\n      if (type === \"selected\") body.ids = [...state.selectedChunks];\n      const data = await API.request(`/api/jobs/${state.job.id}/chunks/export`, { method: \"POST\", body });\n      state.exportId = data.exportId;\n      pollExport();\n      toast(\"Chunk ZIP export started.\");\n    } catch (err) {\n      $(\"export-err\").textContent = err.message;\n      $(\"export-status-row\").classList.add(\"hidden\");\n    }\n  }\n\n  // ── Preview ───────────────────────────────────────────────\n  $(\"preview-close\").addEventListener(\"click\", () => $(\"preview-modal\").classList.add(\"hidden\"));\n  $(\"preview-prev\").addEventListener(\"click\", () => previewNav(-1));\n  $(\"preview-next\").addEventListener(\"click\", () => previewNav(1));\n  $(\"preview-toggle-select\").addEventListener(\"click\", () => {\n    const f = state.frames.find((x) => x.frame_number === state.previewIdx);\n    if (!f) return;\n    if (state.selected.has(f.id)) state.selected.delete(f.id); else state.selected.add(f.id);\n    renderGallery();\n  });\n\n  function openPreview(frameNumber) {\n    state.previewIdx = frameNumber;\n    showPreviewFrame();\n    $(\"preview-modal\").classList.remove(\"hidden\");\n  }\n\n  function previewNav(delta) {\n    const idx = state.frames.findIndex((f) => f.frame_number === state.previewIdx);\n    const next = state.frames[idx + delta];\n    if (next) { state.previewIdx = next.frame_number; showPreviewFrame(); }\n  }\n\n  function showPreviewFrame() {\n    const f = state.frames.find((x) => x.frame_number === state.previewIdx);\n    if (!f) return;\n    $(\"preview-img\").src = f.fullUrl;\n    $(\"preview-title\").textContent = `Frame #${String(f.frame_number).padStart(4, \"0\")}`;\n    $(\"preview-info\").textContent = `#${f.frame_number} · t=${API.fmtTimestamp(f.timestamp)} · ${f.width}x${f.height}px · selected=${state.selected.has(f.id) ? \"yes\" : \"no\"}`;\n    $(\"preview-download\").href = f.fullUrl;\n    $(\"preview-download\").setAttribute(\"download\", `frame_${String(f.frame_number).padStart(4, \"0\")}.jpg`);\n  }\n\n  // ── Export ────────────────────────────────────────────────\n  $(\"export-close\").addEventListener(\"click\", closeExport);\n  function closeExport() {\n    if (state.exportTimer) clearInterval(state.exportTimer);\n    state.exportTimer = null;\n    $(\"export-modal\").classList.add(\"hidden\");\n  }\n\n  async function exportZIP(type) {\n    if (!state.job) return;\n    $(\"export-modal\").classList.remove(\"hidden\");\n    $(\"export-footer\").style.display = \"none\";\n    $(\"export-status-row\").classList.remove(\"hidden\");\n    $(\"export-status-text\").textContent = \"Creating ZIP…\";\n    $(\"export-err\").textContent = \"\";\n    try {\n      const body = { type };\n      if (type === \"selected\") body.frameIds = [...state.selected];\n      const data = await API.request(`/api/jobs/${state.job.id}/export`, { method: \"POST\", body });\n      state.exportId = data.exportId;\n      pollExport();\n      toast(\"Frame ZIP export started.\");\n    } catch (err) {\n      $(\"export-err\").textContent = err.message;\n      $(\"export-status-row\").classList.add(\"hidden\");\n    }\n  }\n\n  function pollExport() {\n    if (state.exportTimer) clearInterval(state.exportTimer);\n    state.exportTimer = setInterval(async () => {\n      try {\n        const data = await API.request(`/api/jobs/exports/${state.exportId}`);\n        $(\"export-status-text\").textContent = `Export status: ${data.status}`;\n        if (data.status === \"completed\") {\n          clearInterval(state.exportTimer); state.exportTimer = null;\n          $(\"export-status-row\").classList.add(\"hidden\");\n          $(\"export-footer\").style.display = \"flex\";\n          $(\"export-download\").href = data.downloadUrl;\n        } else if (data.status === \"failed\") {\n          clearInterval(state.exportTimer); state.exportTimer = null;\n          $(\"export-status-row\").classList.add(\"hidden\");\n          $(\"export-err\").textContent = data.error_message || \"Export failed.\";\n        }\n      } catch (err) {\n        clearInterval(state.exportTimer); state.exportTimer = null;\n        $(\"export-err\").textContent = err.message;\n      }\n    }, 3000);\n  }\n\n  function stopAllTimers() { stopJobTimer(); if (state.exportTimer) { clearInterval(state.exportTimer); state.exportTimer = null; } }\n\n  function esc(s) {\n    const d = document.createElement(\"div\");\n    d.textContent = s == null ? \"\" : String(s);\n    return d.innerHTML;\n  }\n\n  // ── Init ──────────────────────────────────────────────────\n  if (API.token()) {\n    const u = API.getUser();\n    if (u && u.role === \"admin\") enterApp(); else { API.logout(); showAuth(); }\n  } else showAuth();\n})();\n";
